const DEMOS={charizardex:{name:'Charizard ex',query:'Charizard ex'},rayquazaex:{name:'Rayquaza ex',query:'Rayquaza ex'},pikachu:{name:'Pikachu',query:'Pikachu'},dracaufeu:{name:'Dracaufeu',query:'Dracaufeu'}};
const DB_NAME='leon-pokedex-v2',DB_VERSION=1,LIBRARY_STORE='library',PENDING_STORE='pending';
const LANGS=['fr','en','es','de','it','pt','ja'];
let mode='owner',pending=null,selectedFiles=[],library=[],pendingItems=[],guestCards=[],currentResults=[];
const $=s=>document.querySelector(s);
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[c]));
const uid=()=>crypto.randomUUID?crypto.randomUUID():`${Date.now()}-${Math.random()}`;
function toast(t){const e=$('#toast');e.textContent=t;e.classList.add('show');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>e.classList.remove('show'),3200)}
function db(){return new Promise((resolve,reject)=>{const r=indexedDB.open(DB_NAME,DB_VERSION);r.onupgradeneeded=()=>{r.result.createObjectStore(LIBRARY_STORE,{keyPath:'id'});r.result.createObjectStore(PENDING_STORE,{keyPath:'id'});};r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error)})}
async function all(store){const d=await db();return new Promise((res,rej)=>{const r=d.transaction(store,'readonly').objectStore(store).getAll();r.onsuccess=()=>res(r.result||[]);r.onerror=()=>rej(r.error)})}
async function put(store,item){const d=await db();return new Promise((res,rej)=>{const r=d.transaction(store,'readwrite').objectStore(store).put(item);r.onsuccess=()=>res(item);r.onerror=()=>rej(r.error)})}
async function remove(store,id){const d=await db();return new Promise((res,rej)=>{const r=d.transaction(store,'readwrite').objectStore(store).delete(id);r.onsuccess=()=>res();r.onerror=()=>rej(r.error)})}
async function clearStore(store){const d=await db();return new Promise((res,rej)=>{const r=d.transaction(store,'readwrite').objectStore(store).clear();r.onsuccess=()=>res();r.onerror=()=>rej(r.error)})}
async function migrateOld(){const old=JSON.parse(localStorage.getItem('carddex-library-v1')||'[]');if(old.length&&!library.length){for(const c of old)await put(LIBRARY_STORE,{...c,id:c.id||uid(),added:c.added||Date.now(),quantity:c.quantity||1});localStorage.removeItem('carddex-library-v1');library=await all(LIBRARY_STORE)}}
function imageUrl(c,size='high'){return c.image?`${c.image}/${size}.webp`:''}
function priceOf(c){const p=c?.pricing?.cardmarket;if(!p)return null;const n=Number(p.trend??p.avg??p.low);if(!Number.isFinite(n))return null;const d=typeof p.updated==='number'?new Date(p.updated*1000):new Date(p.updated);return {value:n,unit:p.unit||'EUR',updated:Number.isNaN(d.getTime())?new Date().toISOString().slice(0,10):d.toISOString().slice(0,10),source:'TCGdex · Cardmarket'}}
function normaliseType(c){return c.category==='Trainer'?'Dresseur':c.category==='Energy'?'Énergie':(c.types?.[0]||'Incolore')}
function iconFor(type){return {Fire:'🔥',Feu:'🔥',Water:'💧',Eau:'💧',Grass:'🌿',Plante:'🌿',Lightning:'⚡',Électrique:'⚡',Psychic:'🔮',Psy:'🔮',Fighting:'✊',Combat:'✊',Darkness:'🌑',Obscurité:'🌑',Metal:'⚙️',Métal:'⚙️',Dragon:'🐉',Colorless:'⭐',Incolore:'⭐'}[type]||'★'}
function cardFromTCG(c,lang){const attack=c.attacks?.find(a=>a?.name);return {id:uid(),tcgdexId:c.id,name:c.name||'Carte reconnue',lang,category:c.category||'Pokemon',type:normaliseType(c),energy:iconFor(c.types?.[0]||normaliseType(c)),hp:c.hp?`${c.hp} PV`:'—',attack:attack?.name?(attack.damage?`${attack.name} · ${attack.damage}`:attack.name):'—',attacks:c.attacks||[],rarity:c.rarity||'Non indiquée',set:c.set?.name||'Édition inconnue',number:c.localId||c.localId==='0'?c.localId:'?',year:c.set?.releaseDate?.slice(0,4)||'À confirmer',image:imageUrl(c),price:priceOf(c),source:'TCGdex',added:Date.now(),quantity:1}
}
async function tcgdexSearch(query,lang){const u=`https://api.tcgdex.net/v2/${lang}/cards?name=${encodeURIComponent(query)}`;const r=await fetch(u);if(!r.ok)throw new Error('TCGDEX_'+r.status);return r.json()}
async function tcgdexDetail(id,lang){const r=await fetch(`https://api.tcgdex.net/v2/${lang}/cards/${encodeURIComponent(id)}`);if(!r.ok)throw new Error('TCGDEX_'+r.status);const c=await r.json();if(c.set?.id&&!c.set.releaseDate){try{const sr=await fetch(`https://api.tcgdex.net/v2/${lang}/sets/${encodeURIComponent(c.set.id)}`);if(sr.ok){const s=await sr.json();c.set={...c.set,releaseDate:s.releaseDate}}}catch(e){} }return c}
function ocrScript(){return new Promise((res,rej)=>{if(window.Tesseract)return res();const s=document.createElement('script');s.src='https://cdn.jsdelivr.net/npm/tesseract.js@5/dist/tesseract.min.js';s.onload=res;s.onerror=rej;document.head.appendChild(s)})}
async function readText(file){try{await ocrScript();const out=await Tesseract.recognize(file,'eng+fra+deu+spa',{logger:m=>{if(m.status==='recognizing text')$('#analyzeBtn').textContent=`🔎 Lecture ${Math.round((m.progress||0)*100)} %`}});return out.data.text||''}catch(e){return ''}}
function queryWords(text){return text.replace(/[^\p{L}\p{N}' -]/gu,' ').split(/\s+/).filter(w=>w.length>2&&!/^\d+$/.test(w)).slice(0,8).join(' ')}
async function identify(file){const text=await readText(file);const q=queryWords(text);if(!q)return {unknown:true,reason:'OCR local indisponible ou texte trop flou',ocr:text};const chunks=[q.split(' ').slice(0,3).join(' '),q.split(' ').slice(0,2).join(' ')];for(const lang of LANGS){for(const query of chunks){if(!query)continue;try{const brief=await tcgdexSearch(query,lang);const candidate=brief.find(x=>x.image)||brief[0];if(candidate){const detail=await tcgdexDetail(candidate.id,lang);return {...cardFromTCG(detail,lang),ocr:text,confidence:brief.length===1?'élevée':'à vérifier'}}}catch(e){}}}return {unknown:true,reason:`Nom lu « ${q.slice(0,48)} » mais édition non confirmée`,ocr:text}}
function demoCard(key){return {id:uid(),name:DEMOS[key].name,type:key==='pikachu'?'Électrique':'Feu',energy:key==='pikachu'?'⚡':'🔥',hp:'À vérifier',attack:'À vérifier',rarity:'À vérifier',set:'À vérifier',number:'?',year:'À vérifier',image:'',source:'Sélection de test',added:Date.now(),quantity:1,manualQuery:DEMOS[key].query}}
function render(){let cards=mode==='owner'?library:guestCards;const q=$('#searchInput').value.toLowerCase();const ef=$('#energyFilter').value;const sort=$('#sortSelect').value;cards=cards.filter(c=>(c.name||'').toLowerCase().includes(q)&&(!ef||c.type===ef));cards=[...cards].sort((a,b)=>sort==='name'?a.name.localeCompare(b.name):sort==='type'?a.type.localeCompare(b.type):(b.added||0)-(a.added||0));$('#cardCount').textContent=mode==='owner'?library.reduce((n,c)=>n+(c.quantity||1),0):'—';$('#typeCount').textContent=mode==='owner'?new Set(library.map(c=>c.type)).size:'—';$('#rareCount').textContent=mode==='owner'?library.filter(c=>/rare|ultra|illustration/i.test(c.rarity||'')).length:'—';const values=library.map(c=>c.price?.value*(c.quantity||1)).filter(Number.isFinite);$('#valueCount').textContent=values.length?`${values.reduce((a,b)=>a+b,0).toFixed(2)} €`:'—';$('#emptyState').classList.toggle('visible',cards.length===0);$('#library').innerHTML=cards.map((c,i)=>`<article class="card-tile" data-i="${i}"><div class="card-image" style="background:${c.image?'#e9eef7':(c.color||'#f4c542')}">${c.image?`<img src="${esc(c.image)}" alt="${esc(c.name)}" loading="lazy">`:`<span class="card-symbol">${esc(c.energy||'★')}</span>`}<span class="tag">${esc(c.rarity||'À vérifier')}</span></div><div class="tile-meta"><h3>${esc(c.name)}</h3><p>${esc(c.type||'—')} · ${esc(c.hp||'—')} · ×${c.quantity||1}</p></div></article>`).join('');document.querySelectorAll('.card-tile').forEach((el,i)=>el.onclick=()=>showDetail(cards[i]));$('#pendingCount').textContent=`${pendingItems.length} carte${pendingItems.length>1?'s':''}`;$('#pendingPanel').hidden=!pendingItems.length;$('#modeLabel').textContent=mode==='owner'?'Ma collection':'Mode invité';$('#modePill .mode-dot').style.background=mode==='owner'?'var(--red)':'var(--blue)';$('#modalMode').textContent=mode==='owner'?'collection':'invité';$('#privacyText').textContent=mode==='owner'?'les cartes confirmées seront enregistrées dans ce Pokédex':'rien ne sera enregistré';const energies=[...new Set(library.map(c=>c.type).filter(Boolean))].sort();$('#energyFilter').innerHTML='<option value="">Toutes les énergies</option>'+energies.map(e=>`<option>${esc(e)}</option>`).join('')}
function openScan(){selectedFiles=[];pending=null;currentResults=[];$('#photoInput').value='';$('#previewArea').hidden=true;$('#previewArea').innerHTML='';$('#analyzeBtn').disabled=true;$('#analyzeBtn').textContent='✨ Analyser gratuitement';$('#scanModal').hidden=false}
function closeScan(){$('#scanModal').hidden=true}
function setMode(next){mode=next;render()}
function onFiles(files){selectedFiles=[...files];if(!files.length)return;$('#previewArea').hidden=false;$('#previewArea').innerHTML=selectedFiles.slice(0,8).map(f=>`<div class="preview-item"><img alt="Aperçu" src="${URL.createObjectURL(f)}"><small>${esc(f.name)}</small></div>`).join('');$('#analyzeBtn').disabled=false}
function unknownCard(reason){return {id:uid(),name:'Carte à identifier',type:'À vérifier',energy:'?',hp:'—',attack:'À vérifier',rarity:'À vérifier',set:'À vérifier',number:'?',year:'À vérifier',source:reason,unknown:true,added:Date.now(),quantity:1}}
async function analyze(){if(pending?.manualQuery){try{const brief=await tcgdexSearch(pending.manualQuery,'fr');const d=brief.find(x=>x.image)||brief[0];if(d)pending=cardFromTCG(await tcgdexDetail(d.id,'fr'),'fr')}catch(e){}showResultList([pending]);return}if(!pending&&selectedFiles.length){currentResults=[];for(const file of selectedFiles){toast(`Analyse locale de ${file.name}…`);const result=await identify(file);result.fileName=file.name;if(result.unknown){const answer=prompt(`Carte non reconnue automatiquement. Écris son nom pour chercher dans TCGdex (ou Annuler pour la mettre en attente) :`,result.ocr?queryWords(result.ocr).split(' ').slice(0,2).join(' '):'');if(answer){try{const brief=await tcgdexSearch(answer,'fr');const d=brief.find(x=>x.image)||brief[0];result= d?cardFromTCG(await tcgdexDetail(d.id,'fr'),'fr'):result}catch(e){}}}currentResults.push(result)}pending=currentResults.length===1?currentResults[0]:currentResults;showResultList(currentResults)}else if(pending)showResultList(Array.isArray(pending)?pending:[pending])}
function showResultList(results){const c=results[0];if(results.length===1){showDetail(c,true);return}$('#detailContent').innerHTML=`<p class="eyebrow">${results.length} résultats à confirmer</p><h2>Cartes détectées</h2><div class="result-list">${results.map((r,i)=>`<button class="result-row" data-result="${i}">${r.image?`<img src="${esc(r.image)}" alt="">`:'<span class="result-symbol">?</span>'}<span><strong>${esc(r.name)}</strong><small>${esc(r.set||r.source||'À vérifier')}</small></span><span>›</span></button>`).join('')}</div><button class="primary-btn full" id="confirmAll">Ajouter les cartes validées</button>`;$('#detailModal').hidden=false;document.querySelectorAll('[data-result]').forEach(b=>b.onclick=()=>showDetail(results[Number(b.dataset.result)],true));$('#confirmAll').onclick=()=>confirmResults(results)}
function showDetail(c,confirmable=false){const price=c.price?`${c.price.value.toFixed(2)} €`:'Non disponible';const priceNote=c.price?`${c.price.source} · ${c.price.updated}`:'Aucune donnée de prix fournie par le catalogue';const caution=c.unknown?'ⓘ Cette carte n’a pas été identifiée avec assez de certitude. Corrige son nom ou réessaie avec une photo seule, bien cadrée.':`ⓘ ${priceNote}. L’état et l’authenticité nécessitent une vérification humaine : aucune photo ne permet de les garantir.`;$('#detailContent').innerHTML=`<div class="detail-top"><div class="detail-card">${c.image?`<img src="${esc(c.image)}" alt="${esc(c.name)}">`:`<span>${esc(c.energy||'★')}</span>`}</div><div class="detail-content"><p class="eyebrow">Résultat ${confirmable?'à confirmer':'du Pokédex'}</p><h2>${esc(c.name)}</h2><div class="subtitle">${esc(c.type||'—')} · ${esc(c.hp||'—')} · ${esc(c.lang||'')}</div></div></div><div class="info-grid"><div><small>Attaques</small><strong>${esc(c.attack||'—')}</strong></div><div><small>Rareté</small><strong>${esc(c.rarity||'—')}</strong></div><div><small>Édition / numéro</small><strong>${esc(c.set||'—')} · ${esc(c.number||'?')}</strong></div><div><small>Année</small><strong>${esc(c.year||'—')}</strong></div><div><small>Prix en euros</small><strong>${price}</strong></div><div><small>Source</small><strong>${esc(c.source||'—')}</strong></div></div><div class="caution">${esc(caution)}</div>${confirmable?`<button class="primary-btn full" id="confirmCard">${mode==='owner'?'Ajouter à mon Pokédex':'Fermer sans enregistrer'}</button>`:`<button class="secondary-btn full" id="deleteCard">Supprimer cette carte</button>`}`;$('#detailModal').hidden=false;$('#confirmCard')?.addEventListener('click',()=>confirmResults([c]));$('#deleteCard')?.addEventListener('click',async()=>{await remove(LIBRARY_STORE,c.id);library=library.filter(x=>x.id!==c.id);$('#detailModal').hidden=true;render();toast('Carte supprimée')})}
async function confirmResults(results){if(mode==='guest'){toast('Mode invité : rien n’a été enregistré');$('#detailModal').hidden=true;closeScan();return}for(const r of results){if(r.unknown)continue;const same=library.find(c=>c.tcgdexId&&c.tcgdexId===r.tcgdexId);if(same){same.quantity=(same.quantity||1)+1;await put(LIBRARY_STORE,same)}else{await put(LIBRARY_STORE,r);library.push(r)}}$('#detailModal').hidden=true;closeScan();render();toast(`${results.filter(r=>!r.unknown).length} carte(s) ajoutée(s) au Pokédex 🎉`)}
async function savePending(file,result){const item={id:uid(),file,name:file.name,created:Date.now(),result};await put(PENDING_STORE,item);pendingItems.push(item)}
async function retryPending(){if(!pendingItems.length){toast('Aucune analyse en attente');return}const recovered=[];for(const item of pendingItems){if(item.file){const result=await identify(item.file);if(!result.unknown){recovered.push(result);await remove(PENDING_STORE,item.id)}}}pendingItems=await all(PENDING_STORE);render();if(recovered.length){pending=recovered.length===1?recovered[0]:recovered;$('#pendingModal').hidden=true;showResultList(recovered);toast(`${recovered.length} analyse(s) terminée(s)`) }else{toast('Aucune carte n’a pu être reconnue gratuitement pour le moment');$('#pendingModal').hidden=false;renderPending()}}
function renderPending(){$('#pendingList').innerHTML=pendingItems.length?pendingItems.map((p,i)=>`<button class="result-row" data-pending="${i}"><span class="result-symbol">⏳</span><span><strong>${esc(p.name)}</strong><small>Photo conservée localement · à reprendre</small></span><span>›</span></button>`).join(''):'<p class="modal-lead">Aucune analyse en attente.</p>';document.querySelectorAll('[data-pending]').forEach(b=>b.onclick=()=>toast('Réouvre le scanner pour choisir le nom de cette carte'))}
function exportData(){const blob=new Blob([JSON.stringify({format:'leon-pokedex',version:2,exportedAt:new Date().toISOString(),cards:library},null,2)],{type:'application/json'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=`pokedex-leon-${new Date().toISOString().slice(0,10)}.json`;a.click();URL.revokeObjectURL(a.href);toast('Sauvegarde exportée')}
async function importData(file){try{const data=JSON.parse(await file.text());if(!Array.isArray(data.cards))throw Error();for(const c of data.cards){const card={...c,id:c.id||uid(),quantity:c.quantity||1};await put(LIBRARY_STORE,card)}library=await all(LIBRARY_STORE);render();toast(`${data.cards.length} carte(s) restaurée(s)`)}catch(e){toast('Fichier de sauvegarde invalide')}}
$('#scanHero').onclick=openScan;$('#scanNav').onclick=openScan;$('#quickScan').onclick=openScan;$('#emptyScan').onclick=openScan;$('#guestHero').onclick=()=>{setMode('guest');openScan()};$('#quickGuest').onclick=()=>{setMode('guest');openScan()};$('#modeToggle').onclick=()=>setMode(mode==='owner'?'guest':'owner');$('#quickLibrary').onclick=()=>location.hash='library';$('#quickPending').onclick=()=>{$('#pendingModal').hidden=false;renderPending()};$('#retryPending').onclick=retryPending;$('#retryPendingModal').onclick=retryPending;$('#closePending').onclick=()=>$('#pendingModal').hidden=true;$('#closeScan').onclick=closeScan;$('#closeDetail').onclick=()=>$('#detailModal').hidden=true;$('#photoInput').onchange=e=>onFiles(e.target.files);$('#analyzeBtn').onclick=analyze;document.querySelectorAll('[data-demo]').forEach(b=>b.onclick=()=>{pending=demoCard(b.dataset.demo);$('#previewArea').hidden=false;$('#previewArea').innerHTML=`<div class="demo-preview">${pending.energy}<small>Test catalogue</small></div>`;$('#analyzeBtn').disabled=false;toast('Carte de test prête à vérifier')});$('#searchInput').oninput=render;$('#sortSelect').onchange=render;$('#energyFilter').onchange=render;$('#showAll').onclick=()=>{$('#searchInput').value='';render()};$('#exportBtn').onclick=exportData;$('#importInput').onchange=e=>e.target.files[0]&&importData(e.target.files[0]);$('#aboutNav').onclick=()=>toast('Scan local gratuit · TCGdex sans clé · photos invitées non conservées');window.onclick=e=>{if(e.target.classList.contains('modal-backdrop'))e.target.hidden=true};
(async()=>{try{library=await all(LIBRARY_STORE);await migrateOld();pendingItems=await all(PENDING_STORE)}catch(e){toast('Stockage local indisponible dans ce navigateur')}render();if('serviceWorker'in navigator)navigator.serviceWorker.register('sw.js?v=4').catch(()=>{})})();
